issue_context.body:
**Describe the bug**

Using a property decorator causes the class definition to be duplicated in generated code. This makes it impossible to edit the prototype itself in the decorator, since the given target object refers to a duplicate of the class.

I didn't test with non-legacy decorators, since I need Typescript anyway.

**Input code**

```ts
export default class X {
    @networked
    prop: string = "";
}
```

**Config**

(I'm using Rust directly)
```rust
c.process_js_file(
            fm,
            &Options {
                is_module: true,
                config: Some(Config {
                    env: Some(EnvConfig {
                        ..Default::default()
                    }),
                    module: Some(ModuleConfig::CommonJs(
                        Default::default()
                    )),
                    jsc: JscConfig {
                        syntax: Some(Syntax::Typescript(TsConfig {
                            tsx: true,
                            decorators: true,
                            ..Default::default()
                        })),
                        transform: Some(TransformConfig {
                            legacy_decorator: true,
                            ..Default::default()
                        }),
                        ..Default::default()
                    },
                    ..Default::default()
                }),
                ..Default::default()
            },
        )
```

**SWC-generated code**
```js
// ..bunch of boilerplate
var X = (function() {
    var X = function X() {
        'use strict';
        _classCallCheck(this, X);
        _initializerDefineProperty(this, 'prop', _descriptor, this);
    };
    return X;
}(), _descriptor = _applyDecoratedDescriptor(function() {
    var X = function X() {
        'use strict';
        _classCallCheck(this, X);
        _initializerDefineProperty(this, 'prop', _descriptor, this);
    };
    return X;
}().prototype, 'prop', [
    networked
], {
    configurable: true,
    enumerable: true,
    writable: true,
    initializer: function initializer() {
        return '';
    }
}), function() {
    var X = function X() {
        'use strict';
        _classCallCheck(this, X);
        _initializerDefineProperty(this, 'prop', _descriptor, this);
    };
    return X;
}());

```

**Expected behavior**

`_applyDecoratedDescriptor` should receive the final prototype as the first argument. That's what TSC does:
```js
var __decorate = (this && this.__decorate) || function (decorators, target, key, desc) {
    var c = arguments.length, r = c < 3 ? target : desc === null ? desc = Object.getOwnPropertyDescriptor(target, key) : desc, d;
    if (typeof Reflect === "object" && typeof Reflect.decorate === "function") r = Reflect.decorate(decorators, target, key, desc);
    else for (var i = decorators.length - 1; i >= 0; i--) if (d = decorators[i]) r = (c < 3 ? d(r) : c > 3 ? d(target, key, r) : d(target, key)) || r;
    return c > 3 && r && Object.defineProperty(target, key, r), r;
};
let X = /** @class */ (() => {
    class X {
        constructor() {
            this.prop = "";
        }
    }
    __decorate([
        networked
    ], X.prototype, "prop", void 0);
    return X;
})();
export default X;
```

**Version**
Latest github master
